import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# CUDA kernel source
# ----------------------------------------------------------------------
cuda_source = r'''
#include <cuda_fp16.h>

extern "C" __global__
void hinge_loss_kernel(const half* __restrict__ pred,
                       const half* __restrict__ target,
                       float* __restrict__ block_sums,
                       const int64_t total_elems,
                       const int64_t inner_dim) {
    // each thread processes one element
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    float thread_sum = 0.0f;

    if (idx < total_elems) {
        // locate corresponding target (broadcast over inner_dim)
        int batch_idx = idx / inner_dim;
        half p = pred[idx];
        half t = target[batch_idx];
        // 1 - p*t
        half prod = __hmul(p, t);
        half diff = __hsub(__float2half(1.0f), prod);
        // clamp at 0
        half clamped = __hmax(diff, __float2half(0.0f));
        thread_sum = __half2float(clamped);
    }

    // reduction within block
    __shared__ float shmem[256]; // assume blockDim.x <= 256
    int lane = threadIdx.x;
    shmem[lane] = thread_sum;
    __syncthreads();

    // tree reduction
    for (int offset = blockDim.x >> 1; offset > 0; offset >>= 1) {
        if (lane < offset) {
            shmem[lane] += shmem[lane + offset];
        }
        __syncthreads();
    }

    // write block result
    if (lane == 0) {
        block_sums[blockIdx.x] = shmem[0];
    }
}
'''

# ----------------------------------------------------------------------
# Compile the CUDA extension
# ----------------------------------------------------------------------
hinge_mod = load_inline(name='hinge_loss_cuda',
                        cpp_sources='',
                        cuda_sources=cuda_source,
                        functions=['hinge_loss_kernel'],
                        verbose=False)

# ----------------------------------------------------------------------
# Python wrapper for the custom operation
# ----------------------------------------------------------------------
def hinge_loss_fp16(pred: torch.Tensor, target: torch.Tensor) -> torch.Tensor:
    assert pred.is_cuda and target.is_cuda, "Tensors must be CUDA"
    assert pred.dtype == torch.float16 and target.dtype == torch.float16, "FP16 required"
    assert pred.is_contiguous() and target.is_contiguous(), "Contiguous tensors required"

    total_elems = pred.numel()
    batch_size = target.numel()
    inner_dim = total_elems // batch_size
    assert inner_dim * batch_size == total_elems, "Shapes not compatible for broadcast"

    threads = 256
    blocks = (total_elems + threads - 1) // threads

    # allocate per-block partial sums (float32 for accuracy)
    block_sums = torch.empty(blocks, device='cuda', dtype=torch.float32)

    # launch kernel
    hinge_mod.hinge_loss_kernel(
        pred.data_ptr(),
        target.data_ptr(),
        block_sums.data_ptr(),
        total_elems,
        inner_dim,
        grid=(blocks,),
        block=(threads,),
        stream=torch.cuda.current_stream().cuda_stream
    )

    # reduce on GPU
    total_sum = block_sums.sum()
    mean_val = total_sum / total_elems
    # return as half scalar tensor
    return mean_val.to(dtype=torch.float16)

# ----------------------------------------------------------------------
# Model definition using the custom kernel
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    A model that computes Hinge Loss for binary classification tasks
    using a custom CUDA kernel.
    """
    def __init__(self):
        super().__init__()

    def forward(self, predictions: torch.Tensor, targets: torch.Tensor) -> torch.Tensor:
        return hinge_loss_fp16(predictions, targets)

