    batch_size = 32768
    input_shape = (32768,)
    preds = torch.rand(batch_size, *input_shape, device='cuda', dtype=torch.float16)
    # targets in {-1, 1}
    t = (torch.randint(0, 2, (batch_size,), device='cuda', dtype=torch.float16) * 2 - 1)
    return [preds, t]

def get_init_inputs():
    return []

